// Define the slice descriptor
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub struct Slice {
    pub start:  Option<usize>,
    pub stop:   Option<usize>,
    pub step:   Option<usize>,
}

/// Constructs a `Slice` ensuring:
///  1. If `step` is Some, it is strictly positive.
///  2. If both `start` and `stop` are Some, then start <= stop.
/// 
/// Panics if the input constraints are violated.
pub fn s_(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> Slice {
    // Validate that step, if provided, is strictly positive
    if let Some(step_val) = step {
        assert!(step_val > 0, "step must be strictly positive");
    }
    // Validate that start <= stop, if both provided
    if let (Some(start_val), Some(stop_val)) = (start, stop) {
        assert!(
            start_val <= stop_val,
            "when both start and stop are provided, start must be <= stop"
        );
    }
    // Construct and return the slice descriptor
    Slice { start, stop, step }
}

